INSERT INTO item VALUES (198,'Sonic Resistance, Improved','Armor, Shield',NULL,'Yes','Moderate abjuration','7','+42,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Sonic Resistance, Improved\" level=\"8\"><p><b>Sonic Resistance, Improved:</b> As sonic resistance, except it absorbs the first 20 points of sonic damage per attack.</p><p>Moderate abjuration; CL 7th; Craft Magic Arms and Armor, <i>resist energy</i>; Price +42,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (199,'Sonic Resistance, Greater','Armor, Shield',NULL,'Yes','Moderate abjuration','11','+66,000 gp',NULL,'Craft Magic Arms and Armor, resist energy',NULL,NULL,'\n      <div topic=\"Sonic Resistance, Greater\" level=\"8\"><p><b>Sonic Resistance, Greater:</b> As sonic resistance, except it absorbs the first 30 points of sonic damage per attack.</p><p>Moderate abjuration; CL 11th; Craft Magic Arms and Armor, <i>resist energy</i>; Price +66,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (200,'Spell Resistance (13)','Armor',NULL,'Yes','Strong abjuration','15','+2 bonus',NULL,'Craft Magic Arms and Armor, spell resistance',NULL,NULL,'\n      <div topic=\"Spell Resistance\" level=\"8\"><p><b>Spell Resistance:</b> This property grants the armor\'s wearer spell resistance while the armor is worn. The spell resistance can be 13, 15, 17, or 19, depending on the armor.</p><p>Strong abjuration; CL 15th; Craft Magic Arms and Armor, <i>spell resistance</i>; Price +2 bonus (SR 13), +3 bonus (SR 15), +4 bonus (SR 17), or +5 bonus (SR 19).</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (201,'Spell Resistance (15)','Armor',NULL,'Yes','Strong abjuration','15','+3 bonus',NULL,'Craft Magic Arms and Armor, spell resistance',NULL,NULL,'\n      <div topic=\"Spell Resistance\" level=\"8\"><p><b>Spell Resistance:</b> This property grants the armor\'s wearer spell resistance while the armor is worn. The spell resistance can be 13, 15, 17, or 19, depending on the armor.</p><p>Strong abjuration; CL 15th; Craft Magic Arms and Armor, <i>spell resistance</i>; Price +2 bonus (SR 13), +3 bonus (SR 15), +4 bonus (SR 17), or +5 bonus (SR 19).</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (202,'Spell Resistance (17)','Armor',NULL,'Yes','Strong abjuration','15','+4 bonus',NULL,'Craft Magic Arms and Armor, spell resistance',NULL,NULL,'\n      <div topic=\"Spell Resistance\" level=\"8\"><p><b>Spell Resistance:</b> This property grants the armor\'s wearer spell resistance while the armor is worn. The spell resistance can be 13, 15, 17, or 19, depending on the armor.</p><p>Strong abjuration; CL 15th; Craft Magic Arms and Armor, <i>spell resistance</i>; Price +2 bonus (SR 13), +3 bonus (SR 15), +4 bonus (SR 17), or +5 bonus (SR 19).</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (203,'Spell Resistance (19)','Armor',NULL,'Yes','Strong abjuration','15','or +5 bonus',NULL,'Craft Magic Arms and Armor, spell resistance',NULL,NULL,'\n      <div topic=\"Spell Resistance\" level=\"8\"><p><b>Spell Resistance:</b> This property grants the armor\'s wearer spell resistance while the armor is worn. The spell resistance can be 13, 15, 17, or 19, depending on the armor.</p><p>Strong abjuration; CL 15th; Craft Magic Arms and Armor, <i>spell resistance</i>; Price +2 bonus (SR 13), +3 bonus (SR 15), +4 bonus (SR 17), or +5 bonus (SR 19).</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (204,'Undead Controlling','Armor, Shield',NULL,'Yes','Strong necromancy','13','+49,000 gp',NULL,'Craft Magic Arms and Armor, control undead',NULL,NULL,'\n      <div topic=\"Undead Controlling\" level=\"8\"><p><b>Undead Controlling:</b> The wearer of a suit of armor or a shield with this property may control up to 26 HD of undead per day, as the <i>control undead</i> spell. At dawn each day, the wearer loses control of any undead still under his sway. Armor or a shield with this ability appears to be made of bone; this feature is entirely decorative and has no other effect on the armor.</p><p>Strong necromancy; CL 13th; Craft Magic Arms and Armor, <i>control undead</i>; Price +49,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (205,'Wild','Armor, Shield',NULL,'Yes','Moderate transmutation','9','+3 bonus',NULL,'Craft Magic Arms and Armor, baleful polymorph',NULL,NULL,'\n      <div topic=\"Wild\" level=\"8\"><p><b>Wild:</b> The wearer of a suit of armor or a shield with this ability preserves his armor bonus (and any enhancement bonus) while in a wild shape. Armor and shields with this ability usually appear to be made covered in leaf patterns. While the wearer is in a wild shape, the armor cannot be seen.</p><p>Moderate transmutation; CL 9th; Craft Magic Arms and Armor, <i>baleful polymorph</i>; Price +3 bonus.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"6\" curcol=\"2\">\n<td colspan=\"5\"><b>Table: Specific Armors</b><br/></td> \n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td><b>Minor</b><br/></td>\n<td><b>Medium</b><br/></td>\n<td><b>Major</b><br/></td>\n<td><b>Specific Armor</b><br/></td>\n<td><b>Market Price</b><br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>01-50<br/></td>\n<td>01-25<br/></td>\n<td>-<br/></td>\n<td>Mithral shirt<br/></td>\n<td>1,100 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>51-80<br/></td>\n<td>26-45<br/></td>\n<td>-<br/></td>\n<td>Dragonhide plate<br/></td>\n<td>3,300 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>81-100<br/></td>\n<td>46-57<br/></td>\n<td>-<br/></td>\n<td>Elven chain<br/></td>\n<td>4,150 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>58-67<br/></td>\n<td>-<br/></td>\n<td><i>Rhino hide</i><br/></td>\n<td>5,165 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>68-82<br/></td>\n<td>01-10<br/></td>\n<td>Adamantine breastplate<br/></td>\n<td>10,200 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>83-97<br/></td>\n<td>11-20<br/></td>\n<td>Dwarven plate<br/></td>\n<td>16,500 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>98-100<br/></td>\n<td>21-32<br/></td>\n<td><i>Banded mail of luck</i><br/></td>\n<td>18,900 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>33-50<br/></td>\n<td><i>Celestial armor</i><br/></td>\n<td>22,400 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>51-60<br/></td>\n<td><i>Plate armor of the deep</i><br/></td>\n<td>24,650 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>61-75<br/></td>\n<td><i>Breastplate of command</i><br/></td>\n<td>25,400 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>76-90<br/></td>\n<td>Mithral full plate of speed<br/></td>\n<td>26,500 gp<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>91-100<br/></td>\n<td><i>Demon armor</i><br/></td>\n<td>52,260 gp<br/></td>\n\n</tr>\n</table><p/>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (206,'Adamantine Breastplate','Armor, Shield',NULL,'No','No aura (nonmagical)',NULL,'10,200 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Adamantine Breastplate\" level=\"8\"><p><b>Adamantine Breastplate:</b> This nonmagical breastplate is made of adamantine, giving its wearer damage reduction of 2/-.</p><p>No aura (nonmagical); Price 10,200 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (207,'Banded Mail of Luck','Armor',NULL,'No','Strong enchantment','12','18,900 gp',NULL,'Craft Magic Arms and Armor, bless','10,150 gp + 700 XP',NULL,'\n      <div topic=\"Banded Mail of Luck\" level=\"8\"><p><b>Banded Mail of Luck:</b> Ten 100-gp gems adorn this <i>+3 banded mail</i>. Once per week, the armor allows its wearer to require that an attack roll made against him be rerolled. He must take whatever consequences come from the second roll. The wearer\'s player must decide whether to have the attack roll rerolled before damage is rolled.</p><p>Strong enchantment; CL 12th; Craft Magic Arms and Armor, <i>bless</i>; Price 18,900 gp; Cost 10,150 gp + 700 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (208,'Breastplate of Command','Armor',NULL,'No','Strong enchantment','15','25,400 gp',NULL,'Craft Magic Arms and Armor, mass charm monster','10,975 gp + 850 XP',NULL,'\n      <div topic=\"Breastplate of Command\" level=\"8\"><p><b>Breastplate of Command:</b> This finely crafted <i>+2 breastplate</i> radiates a powerful aura of magic. When worn, the armor bestows a dignified and commanding aura upon its owner. The wearer gains a +2 competence bonus on all Charisma checks, including turning checks and Charisma-based skill checks. The wearer also gains a +2 competence bonus to his Leadership score. Friendly troops within 360 feet of the user become braver than normal. Since the effect arises in great part from the distinctiveness of the armor, the wearer cannot hide or conceal herself in any way and still have the effect function.</p><p>Strong enchantment; CL 15th; Craft Magic Arms and Armor, <i>mass charm monster</i>; Price 25,400 gp; Cost 10,975 gp + 850 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (209,'Celestial Armor','Armor',NULL,'No','Faint transmutation [good]','5','22,400 gp',NULL,'Craft Magic Arms and Armor, creator must be good, fly','12,550 gp + 1,004 XP',NULL,'\n      <div topic=\"Celestial Armor\" level=\"8\"><p><b>Celestial Armor:</b> This bright silver or gold <i>+3 chainmail</i> is so fine and light that it can be worn under normal clothing without betraying its presence. It has a maximum Dexterity bonus of +8, an armor check penalty of -2, and an arcane spell failure chance of 15%. It is considered light armor, weighs 20 pounds, and it allows the wearer to use <i>fly</i> on command (as the spell) once per day.</p><p>Faint transmutation [good]; CL 5th; Craft Magic Arms and Armor, creator must be good, <i>fly</i>; Price 22,400 gp; Cost 12,550 gp + 1,004 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (210,'Demon Armor','Armor',NULL,'No','Strong necromancy [evil]','13','52,260 gp',NULL,'Craft Magic Arms and Armor, contagion','26,130 gp + 2,090 XP',NULL,'\n      <div topic=\"Demon Armor\" level=\"8\"><p><b>Demon Armor:</b> This plate armor is fashioned to make the wearer appear to be a demon. The helmet is shaped to look like a horned demon head, and its wearer looks out of the open, tooth-filled mouth. This <i>+4 full plate</i> allows the wearer to make claw attacks that deal 1d10 points of damage, strike as +1 weapons, and afflict the target as if she had been struck by a <i>contagion</i> spell (Fortitude DC 14 negates). Use of <i>contagion</i> requires a normal melee attack with the claws. The \'claws\' are built into the armor\'s vambraces and gauntlets.</p><p>The armor bestows one negative level on any nonevil creature wearing it. This negative level persists as long as the armor is worn and disappears when the armor is removed. The negative level never results in actual level loss, but it cannot be overcome in any way (including <i>restoration</i> spells) while the armor is worn.</p><p>Strong necromancy [evil]; CL 13th; Craft Magic Arms and Armor, <i>contagion</i>; Price 52,260 gp; Cost 26,130 gp + 2,090 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (211,'Dragonhide Plate','Armor, Shield',NULL,'No','No aura (nonmagical)',NULL,'3,300 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Dragonhide Plate\" level=\"8\"><p><b>Dragonhide Plate:</b> This suit of full plate is made of dragonhide, rather than metal, so druids can wear it. It is otherwise identical to masterwork full plate.</p><p>No aura (nonmagical); Price 3,300 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (212,'Dwarven Plate','Armor, Shield',NULL,'No','No aura (nonmagical)',NULL,'16,500 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Dwarven Plate\" level=\"8\"><p><b>Dwarven Plate:</b> This full plate is made of adamantine, giving its wearer damage reduction of 3/-.</p><p>No aura (nonmagical); Price 16,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (213,'Elven Chain','Armor',NULL,'No','No aura (nonmagical)',NULL,'4,150 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Elven Chain\" level=\"8\"><p><b>Elven Chain:</b> This extremely light chainmail is made of very fine mithral links. Speed while wearing elven chain is 30 feet for Medium creatures, or 20 feet for Small. The armor has an arcane spell failure chance of 20%, a maximum Dexterity bonus of +4, and an armor check penalty of -2. It is considered light armor and weighs 20 pounds.</p><p>No aura (nonmagical); Price 4,150 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (214,'Mithral Full Plate of Speed','Armor',NULL,'No','Faint transmutation','5','26,500 gp',NULL,'Craft Magic Arms and Armor, haste',NULL,NULL,'\n      <div topic=\"Mithral Full Plate of Speed\" level=\"8\"><p><b>Mithral Full Plate of Speed:</b> As a free action, the wearer of this fine set of <i>+1 mithral full plate</i> can activate it, enabling her to act as though affected by a <i>haste</i> spell for up to 10 rounds each day. The duration of the <i>haste</i> effect need not be consecutive rounds.</p><p>Speed while wearing a suit of mithral full plate is 20 feet for Medium creatures, or 15 feet for Small. The armor has an arcane spell failure chance of 25%, a maximum Dexterity bonus of +3, and an armor check penalty of -3. It is considered medium armor and weighs 25 pounds.</p><p>Faint transmutation; CL 5th; Craft Magic Arms and Armor, <i>haste</i>; Price 26,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (215,'Mithral Shirt','Armor',NULL,'No','No aura (nonmagical)',NULL,'1,100 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Mithral Shirt\" level=\"8\"><p><b>Mithral Shirt:</b> This extremely light chain shirt is made of very fine mithral links. Speed while wearing a mithral shirt is 30 feet for Medium creatures, or 20 feet for Small. The armor has an arcane spell failure chance of 10%, a maximum Dexterity bonus of +6, and no armor check penalty. It is considered light armor and weighs 10 pounds.</p><p>No aura (nonmagical); Price 1,100 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (216,'Plate Armor of the Deep','Armor',NULL,'No','Moderate abjuration','11','24,650 gp',NULL,'Craft Magic Arms and Armor, freedom of movement, water breathing, tongues','17,150 gp + 600 XP',NULL,'\n      <div topic=\"Plate Armor of the Deep\" level=\"8\"><p><b>Plate Armor of the Deep:</b> This <i>+1 full plate</i> is decorated with a wave and fish motif. The wearer of <i>plate armor of the deep</i> is treated as unarmored for purposes of Swim checks. The wearer can breathe underwater and can converse with any creature with a language that breathes water.</p><p>Moderate abjuration; CL 11th; Craft Magic Arms and Armor, <i>freedom of movement</i>,  <i>water breathing</i>,  <i>tongues</i>; Price 24,650 gp; Cost 17,150 gp + 600 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (217,'Rhino Hide','Armor, Shield',NULL,'No','Moderate transmutation','9','5,165 gp',NULL,'Craft Magic Arms and Armor, bull\'s strength','2,665 gp + 200 XP',NULL,'\n      <div topic=\"Rhino Hide\" level=\"8\"><p><b>Rhino Hide:</b> This <i>+2 hide</i> armor is made from rhinoceros hide. In addition to granting a +2 enhancement bonus to AC, it has a -1 armor check penalty and deals an additional 2d6 points of damage on any successful charge attack made by the wearer, including a mounted charge.</p><p>Moderate transmutation; CL 9th; Craft Magic Arms and Armor, <i>bull\'s strength</i>; Price 5,165 gp; Cost 2,665 gp + 200 XP.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"6\" curcol=\"2\">\n<td colspan=\"5\"><b>Table: Specific Shields</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td><b>Minor</b><br/></td>\n<td><b>Medium</b><br/></td>\n<td><b>Major</b><br/></td>\n<td><b>Specific Shield</b><br/></td>\n<td><b>Market Price</b><br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>01-30<br/></td>\n<td>01-20<br/></td>\n<td>-<br/></td>\n<td>Darkwood buckler<br/></td>\n<td>205 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>31-80<br/></td>\n<td>21-45<br/></td>\n<td>-<br/></td>\n<td>Darkwood shield<br/></td>\n<td>257 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>81-95<br/></td>\n<td>46-70<br/></td>\n<td>-<br/></td>\n<td>Mithral heavy shield<br/></td>\n<td>1,020 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>96-100<br/></td>\n<td>71-85<br/></td>\n<td>01-20<br/></td>\n<td><i>Caster\'s shield</i><br/></td>\n<td>3,153 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>86-90<br/></td>\n<td>21-40<br/></td>\n<td><i>Spined shield</i><br/></td>\n<td>5,580 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>91-95<br/></td>\n<td>41-60<br/></td>\n<td><i>Lion\'s shield</i><br/></td>\n<td>9,170 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>96-100<br/></td>\n<td>61-90<br/></td>\n<td><i>Winged shield</i><br/></td>\n<td>17,257 gp<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>91-100<br/></td>\n<td><i>Absorbing shield</i><br/></td>\n<td>50,170 gp<br/></td>\n\n</tr>\n</table><p/>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (218,'Absorbing Shield','Shield','Shield','No','Strong transmutation','17','50,170 gp',NULL,'Craft Magic Arms and Armor, disintegrate','25,170 gp + 2,000 XP',NULL,'\n      <div topic=\"Absorbing Shield\" level=\"8\"><p><b>Absorbing Shield:</b> This <i>+1 heavy steel shield</i> is flat black and seems to absorb light. Once every two days, on command, it can <i>disintegrate</i> an object that it touches, as the spell but requiring a melee touch attack.</p><p>Strong transmutation; CL 17th; Craft Magic Arms and Armor, <i>disintegrate</i>; Price 50,170 gp; Cost 25,170 gp + 2,000 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (219,'Caster\'s Shield','Shield','Shield','No','Moderate abjuration','6','3,153 gp (plus the value of the scroll spell if one is currently scribed)',NULL,'Craft Magic Arms and Armor, Scribe Scroll, creator must be at least 6th level','1,653 gp + 120 XP',NULL,'\n      <div topic=\"Caster\'s Shield\" level=\"8\"><p><b>Caster\'s Shield:</b> This <i>+1 light wooden shield</i> has a small leather strip on the back on which a spellcaster can scribe a single spell as on a scroll. A spell so scribed has only half the base raw material cost. Experience point and component costs remain the same. The strip cannot accommodate spells of higher than 3rd level. The strip is reusable.</p><p>A random <i>caster\'s shield</i> has a 50% chance of having a single medium scroll spell on it. The spell is divine (01-80 on d%) or arcane (81-100).</p><p>A <i>caster\'s shield</i> has a 5% arcane spell failure chance.</p><p>Moderate abjuration; CL 6th; Craft Magic Arms and Armor, Scribe Scroll, creator must be at least 6th level; Price 3,153 gp (plus the value of the scroll spell if one is currently scribed); Cost 1,653 gp + 120 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (220,'Darkwood Buckler','Shield','Shield','No','No aura (nonmagical)',NULL,'205 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Darkwood Buckler\" level=\"8\"><p><b>Darkwood Buckler:</b> This nonmagical light wooden shield is made out of darkwood. It has no enhancement bonus, but its construction material makes it lighter than a normal wooden shield. It weighs 2-1/2 pounds and has no armor check penalty.</p><p>No aura (nonmagical); Price 205 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (221,'Darkwood Shield','Shield','Shield','No','No aura (nonmagical)',NULL,'257 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Darkwood Shield\" level=\"8\"><p><b>Darkwood Shield:</b> This nonmagical heavy wooden shield is made out of darkwood. It has no enhancement bonus, but its construction material makes it lighter than a normal wooden shield.</p><p>It weighs 5 pounds and has no armor check penalty.</p><p>No aura (nonmagical); Price 257 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (222,'Lion\'s Shield','Shield','Shield','No','Moderate conjuration','10','9,170 gp',NULL,'Craft Magic Arms and Armor, summon nature\'s ally IV','4,670 gp + 360 XP',NULL,'\n      <div topic=\"Lion\'s Shield\" level=\"8\"><p><b>Lion\'s Shield:</b> This <i>+2 heavy steel shield</i> is fashioned to appear to be a roaring lion\'s head. Three times per day as a free action, the lion\'s head can be commanded to attack (independently of the shield wearer), biting with the wielder\'s base attack bonus (including multiple attacks, if the wielder has them) and dealing 2d6 points of damage. This attack is in addition to any actions performed by the wielder.</p><p>Moderate conjuration; CL 10th; Craft Magic Arms and Armor, <i>summon nature\'s ally IV</i>; Price 9,170 gp; Cost 4,670 gp + 360 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (223,'Mithral Heavy Shield','Shield','Shield','No','No aura (nonmagical)',NULL,'1,020 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Mithral Heavy Shield\" level=\"8\"><p><b>Mithral Heavy Shield:</b> This heavy shield is made of mithral and thus is much lighter than a standard steel shield. It has a 5% arcane spell failure chance and no armor check penalty. It weighs 5 pounds.</p><p>No aura (nonmagical); Price 1,020 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (224,'Spined Shield','Shield','Shield','No','Moderate evocation','6','5,580 gp',NULL,'Craft Magic Arms and Armor, magic missile','2,740 gp + 223 XP',NULL,'\n      <div topic=\"Spined Shield\" level=\"8\"><p><b>Spined Shield:</b> This <i>+1 heavy steel shield</i> is covered in spines. It acts as a normal spiked shield. On command up to three times per day, the shield\'s wearer can fire one of the shield\'s spines. A fired spine has a +1 enhancement bonus, a range increment of 120 feet, and deals 1d10 points of damage (19-20/x2). Fired spines regenerate each day.</p><p>Moderate evocation; CL 6th; Craft Magic Arms and Armor, <i>magic missile</i>; Price 5,580 gp; Cost 2,740 gp + 223 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (225,'Winged Shield','Shield','Shield','No','Faint transmutation','5','17,257 gp',NULL,'Craft Magic Arms and Armor, fly','8,628 gp and 5 sp + 690 XP',NULL,'\n      <div topic=\"Winged Shield\" level=\"8\"><p><b>Winged Shield:</b> This round heavy wooden shield has a +3 enhancement bonus. Small, feathered wings encircle the shield.</p><p>Once per day it can be commanded to <i>fly</i> (as the spell), carrying the wielder. The shield can carry up to 133 pounds and move at 60 feet per round, or up to 266 pounds and move at 40 feet per round.</p><p>Faint transmutation; CL 5th; Craft Magic Arms and Armor, <i>fly</i>; Price 17,257 gp; Cost 8,628 gp and 5 sp + 690 XP.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (226,'Anarchic','Weapon',NULL,'Yes','Moderate evocation [chaotic]','7','+2 bonus',NULL,'Craft Magic Arms and Armor, chaos hammer, creator must be chaotic',NULL,NULL,'\n      <div topic=\"Anarchic\" level=\"8\"><p><b>Anarchic:</b> An anarchic weapon is chaotically aligned and infused with the power of chaos. It makes the weapon chaos-aligned and thus bypasses the corresponding damage reduction. It deals an extra 2d6 points of damage against all of lawful alignment. It bestows one negative level on any lawful creature attempting to wield it. The negative level remains as long as the weapon is in hand and disappears when the weapon is no longer wielded. This negative level never results in actual level loss, but it cannot be overcome in any way (including <i>restoration</i> spells) while the weapon is wielded. Bows, crossbows, and slings so crafted bestow the chaotic power upon their ammunition.</p><p>Moderate evocation [chaotic]; CL 7th; Craft Magic Arms and Armor, <i>chaos hammer</i>,  creator must be chaotic; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (227,'Axiomatic','Weapon',NULL,'Yes','Moderate evocation [lawful]','7','+2 bonus',NULL,'Craft Magic Arms and Armor, order\'s wrath, creator must be lawful',NULL,NULL,'\n      <div topic=\"Axiomatic\" level=\"8\"><p><b>Axiomatic:</b> An axiomatic weapon is lawfully aligned and infused with the power of law. It makes the weapon law-aligned and thus bypasses the corresponding damage reduction. It deals an extra 2d6 points of damage against all of chaotic alignment. It bestows one negative level on any chaotic creature attempting to wield it. The negative level remains as long as the weapon is in hand and disappears when the weapon is no longer wielded. This negative level never results in actual level loss, but it cannot be overcome in any way (including <i>restoration</i> spells) while the weapon is wielded. Bows, crossbows, and slings so crafted bestow the lawful power upon their ammunition.</p><p>Moderate evocation [lawful]; CL 7th; Craft Magic Arms and Armor, <i>order\'s wrath</i>,  creator must be lawful; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (228,'Bane','Weapon',NULL,'Yes','Moderate conjuration','8','+1 bonus',NULL,'Craft Magic Arms and Armor, summon monster I',NULL,NULL,'\n      <div topic=\"Bane\" level=\"8\"><p><b>Bane:</b> A bane weapon excels at attacking one type or subtype of creature. Against its designated foe, its effective enhancement bonus is +2 better than its normal enhancement bonus. It deals an extra 2d6 points of damage against the foe. Bows, crossbows, and slings so crafted bestow the bane quality upon their ammunition. To randomly determine a weapon\'s designated foe, roll on the following table.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>d%</b><br/></td>\n<td><b>Designated Foe</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>01-05<br/></td>\n<td>Aberrations<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>06-09<br/></td>\n<td>Animals<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10-16<br/></td>\n<td>Constructs<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>17-22<br/></td>\n<td>Dragons<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>23-27<br/></td>\n<td>Elementals<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>28-32<br/></td>\n<td>Fey<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>33-39<br/></td>\n<td>Giants<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>40<br/></td>\n<td>Humanoids, aquatic<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>41-42<br/></td>\n<td>Humanoids, dwarf<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>43-44<br/></td>\n<td>Humanoids, elf<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>45<br/></td>\n<td>Humanoids, gnoll<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>46<br/></td>\n<td>Humanoids, gnome<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>47-49<br/></td>\n<td>Humanoids, goblinoid<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>50<br/></td>\n<td>Humanoids, halfling<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>51-54<br/></td>\n<td>Humanoids, human<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>55-57<br/></td>\n<td>Humanoids, reptilian<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>58-60<br/></td>\n<td>Humanoids, orc<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>61-65<br/></td>\n<td>Magical beasts<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>66-70<br/></td>\n<td>Monstrous humanoids<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>71-72<br/></td>\n<td>Oozes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>73<br/></td>\n<td>Outsiders, air<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>74-76<br/></td>\n<td>Outsiders, chaotic<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>77<br/></td>\n<td>Outsiders, earth<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>78-80<br/></td>\n<td>Outsiders, evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>81<br/></td>\n<td>Outsiders, fire<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>82-84<br/></td>\n<td>Outsiders, good<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>85-87<br/></td>\n<td>Outsiders, lawful<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>88<br/></td>\n<td>Outsiders, water<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>89-90<br/></td>\n<td>Plants<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>91-98<br/></td>\n<td>Undead<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>99-100<br/></td>\n<td>Vermin<br/></td>\n\n</tr>\n</table><p>Moderate conjuration; CL 8th; Craft Magic Arms and Armor, <i>summon monster I</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (229,'Brilliant Energy','Weapon',NULL,'Yes','Strong transmutation','16','+4 bonus',NULL,'Craft Magic Arms and Armor, gaseous form, continual flame',NULL,NULL,'\n      <div topic=\"Brilliant Energy\" level=\"8\"><p><b>Brilliant Energy:</b> A brilliant energy weapon has its significant portion transformed into light, although this does not modify the item\'s weight. It always gives off light as a torch (20-foot radius). A brilliant energy weapon ignores nonliving matter. Armor and shield bonuses to AC (including any enhancement bonuses to that armor) do not count against it because the weapon passes through armor. (Dexterity, deflection, dodge, natural armor, and other such bonuses still apply.) A brilliant energy weapon cannot harm undead, constructs, and objects. This property can only be applied to melee weapons, thrown weapons, and ammunition.</p><p>Strong transmutation; CL 16th; Craft Magic Arms and Armor, <i>gaseous form</i>,  <i>continual flame</i>; Price +4 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (230,'Dancing','Weapon',NULL,'Yes','Strong transmutation','15','+4 bonus',NULL,'Craft Magic Arms and Armor, animate objects',NULL,NULL,'\n      <div topic=\"Dancing\" level=\"8\"><p><b>Dancing:</b> As a standard action, a dancing weapon can be loosed to attack on its own. It fights for 4 rounds using the base attack bonus of the one who loosed it and then drops. While dancing, it cannot make attacks of opportunity, and the person who activated it is not considered armed with the weapon. In all other respects, it is considered wielded or attended by the creature for all maneuvers and effects that target items. While dancing, it takes up the same space as the activating character and can attack adjacent foes (weapons with reach can attack opponents up to 10 feet away). The dancing weapon accompanies the person who activated it everywhere, whether she moves by physical or magical means. If the wielder who loosed it has an unoccupied hand, she can grasp it while it is attacking on its own as a free action; when so retrieved the weapon can\'t dance (attack on its own) again for 4 rounds.</p><p>Strong transmutation; CL 15th; Craft Magic Arms and Armor, <i>animate objects</i>; Price +4 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (231,'Defending','Weapon',NULL,'Yes','Moderate abjuration','8','+1 bonus',NULL,'Craft Magic Arms and Armor, shield or shield of faith',NULL,NULL,'\n      <div topic=\"Defending\" level=\"8\"><p><b>Defending:</b> A defending weapon allows the wielder to transfer some or all of the sword\'s enhancement bonus to his AC as a bonus that stacks with all others. As a free action, the wielder chooses how to allocate the weapon\'s enhancement bonus at the start of his turn before using the weapon, and the effect to AC lasts until his next turn.</p><p>Moderate abjuration; CL 8th; Craft Magic Arms and Armor, <i>shield</i> or <i>shield of faith</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (232,'Disruption','Weapon',NULL,'Yes','Strong conjuration','14','+2 bonus',NULL,'Craft Magic Arms and Armor, heal',NULL,NULL,'\n      <div topic=\"Disruption\" level=\"8\"><p><b>Disruption:</b> A weapon of disruption is the bane of all undead. Any undead creature struck in combat must succeed on a DC 14 Will save or be destroyed. A weapon of disruption must be a bludgeoning weapon. (If you roll this property randomly for a piercing or slashing weapon, reroll.)</p><p>Strong conjuration; CL 14th; Craft Magic Arms and Armor, <i>heal</i>; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (233,'Distance','Weapon',NULL,'Yes','Moderate divination','6','+1 bonus',NULL,'Craft Magic Arms and Armor, clairaudience/clairvoyance',NULL,NULL,'\n      <div topic=\"Distance\" level=\"8\"><p><b>Distance:</b> This property can only be placed on a ranged weapon. A weapon of distance has double the range increment of other weapons of its kind.</p><p>Moderate divination; CL 6th; Craft Magic Arms and Armor, <i>clairaudience/clairvoyance</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (234,'Flaming','Weapon',NULL,'Yes','Moderate evocation','10','+1 bonus',NULL,'Craft Magic Arms and Armor and flame blade, flame strike, or fireball',NULL,NULL,'\n      <div topic=\"Flaming\" level=\"8\"><p><b>Flaming:</b> Upon command, a flaming weapon is sheathed in fire. The fire does not harm the wielder. The effect remains until another command is given. A flaming weapon deals an extra 1d6 points of fire damage on a successful hit. Bows, crossbows, and slings so crafted bestow the fire energy upon their ammunition.</p><p>Moderate evocation; CL 10th; Craft Magic Arms and Armor and <i>flame blade</i>,  <i>flame strike</i>,  or <i>fireball</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (235,'Flaming Burst','Weapon',NULL,'Yes','Strong evocation','12','+2 bonus',NULL,'Craft Magic Arms and Armor and flame blade, flame strike, or fireball',NULL,NULL,'\n      <div topic=\"Flaming Burst\" level=\"8\"><p><b>Flaming Burst:</b> A flaming burst weapon functions as a flaming weapon that also explodes with flame upon striking a successful critical hit. The fire does not harm the wielder. In addition to the extra fire damage from the flaming ability (see above), a flaming burst weapon deals an extra 1d10 points of fire damage on a successful critical hit. If the weapon\'s critical multiplier is x3, add an extra 2d10 points of fire damage instead, and if the multiplier is x4, add an extra 3d10 points of fire damage. Bows, crossbows, and slings so crafted bestow the fire energy upon their ammunition.</p><p>Even if the flaming ability is not active, the weapon still deals its extra fire damage on a successful critical hit.</p><p>Strong evocation; CL 12th; Craft Magic Arms and Armor and <i>flame blade</i>,  <i>flame strike</i>,  or <i>fireball</i>; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (236,'Frost','Weapon',NULL,'Yes','Moderate evocation','8','+1 bonus',NULL,'Craft Magic Arms and Armor, chill metal or ice storm',NULL,NULL,'\n      <div topic=\"Frost\" level=\"8\"><p><b>Frost:</b> Upon command, a frost weapon is sheathed in icy cold. The cold does not harm the wielder. The effect remains until another command is given. A frost weapon deals an extra 1d6 points of cold damage on a successful hit. Bows, crossbows, and slings so crafted bestow the cold energy upon their ammunition.</p><p>Moderate evocation; CL 8th; Craft Magic Arms and Armor, <i>chill metal</i> or <i>ice storm</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (237,'Ghost Touch','Weapon',NULL,'Yes','Moderate conjuration','9','+1 bonus',NULL,'Craft Magic Arms and Armor, plane shift',NULL,NULL,'\n      <div topic=\"Ghost Touch\" level=\"8\"><p><b>Ghost Touch:</b> A ghost touch weapon deals damage normally against incorporeal creatures, regardless of its bonus. (An incorporeal creature\'s 50% chance to avoid damage does not apply to attacks with ghost touch weapons.) The weapon can be picked up and moved by an incorporeal creature at any time. A manifesting ghost can wield the weapon against corporeal foes. Essentially, a ghost touch weapon counts as either corporeal or incorporeal at any given time, whichever is more beneficial to the wielder.</p><p>Moderate conjuration; CL 9th; Craft Magic Arms and Armor, <i>plane shift</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (238,'Holy','Weapon',NULL,'Yes','Moderate evocation [good]','7','+2 bonus',NULL,'Craft Magic Arms and Armor, holy smite, creator must be good',NULL,NULL,'\n      <div topic=\"Holy\" level=\"8\"><p><b>Holy:</b> A holy weapon is imbued with holy power. This power makes the weapon good-aligned and thus bypasses the corresponding damage reduction. It deals an extra 2d6 points of damage against all of evil alignment. It bestows one negative level on any evil creature attempting to wield it. The negative level remains as long as the weapon is in hand and disappears when the weapon is no longer wielded. This negative level never results in actual level loss, but it cannot be overcome in any way (including <i>restoration</i> spells) while the weapon is wielded. Bows, crossbows, and slings so crafted bestow the holy power upon their ammunition.</p><p>Moderate evocation [good]; CL 7th; Craft Magic Arms and Armor, <i>holy smite</i>,  creator must be good; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (239,'Icy Burst','Weapon',NULL,'Yes','Moderate evocation','10','+2 bonus',NULL,'Craft Magic Arms and Armor, chill metal or ice storm',NULL,NULL,'\n      <div topic=\"Icy Burst\" level=\"8\"><p><b>Icy Burst:</b> An icy burst weapon functions as a frost weapon that also explodes with frost upon striking a successful critical hit. The frost does not harm the wielder. In addition to the extra damage from the frost ability, an icy burst weapon deals an extra 1d10 points of cold damage on a successful critical hit. If the weapon\'s critical multiplier is x3, add an extra 2d10 points of cold damage instead, and if the multiplier is x4, add an extra 3d10 points. Bows, crossbows, and slings so crafted bestow the cold energy upon their ammunition.</p><p>Even if the frost ability is not active, the weapon still deals its extra cold damage on a successful critical hit.</p><p>Moderate evocation; CL 10th; Craft Magic Arms and Armor, <i>chill metal</i> or <i>ice storm</i>; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (240,'Keen','Weapon',NULL,'Yes','Moderate transmutation','10','+1 bonus',NULL,'Craft Magic Arms and Armor, keen edge',NULL,NULL,'\n      <div topic=\"Keen\" level=\"8\"><p><b>Keen:</b> This ability doubles the threat range of a weapon. Only piercing or slashing weapons can be keen. (If you roll this property randomly for an inappropriate weapon, reroll.) This benefit doesn\'t stack with any other effect that expands the threat range of a weapon (such as the <i>keen edge</i> spell or the Improved Critical feat).</p><p>Moderate transmutation; CL 10th; Craft Magic Arms and Armor, <i>keen edge</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (241,'Ki Focus','Weapon',NULL,'Yes','Moderate transmutation','8','+1 bonus',NULL,'Craft Magic Arms and Armor, creator must be a monk',NULL,NULL,'\n      <div topic=\"Ki Focus\" level=\"8\"><p><b><i>ki</i> Focus:</b> The magic weapon serves as a channel for the wielder\'s <i>ki</i>, allowing her to use her special <i>ki</i> attacks through the weapon as if they were unarmed attacks. These attacks include the monk\'s stunning attack, <i>ki</i> strike, and quivering palm, as well as the Stunning Fist feat. Only melee weapons can have the <i>ki</i> focus ability.</p><p>Moderate transmutation; CL 8th; Craft Magic Arms and Armor, creator must be a monk; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (242,'Merciful','Weapon',NULL,'Yes','Faint conjuration','5','+1 bonus',NULL,'Craft Magic Arms and Armor, cure light wounds',NULL,NULL,'\n      <div topic=\"Merciful\" level=\"8\"><p><b>Merciful:</b> The weapon deals an extra 1d6 points of damage, and all damage it deals is nonlethal damage. On command, the weapon suppresses this ability until commanded to resume it. Bows, crossbows, and slings so crafted bestow the merciful effect upon their ammunition.</p><p>Faint conjuration; CL 5th; Craft Magic Arms and Armor, <i>cure light wounds</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (243,'Mighty Cleaving','Weapon',NULL,'Yes','Moderate evocation','8','+1 bonus',NULL,'Craft Magic Arms and Armor, divine power',NULL,NULL,'\n      <div topic=\"Mighty Cleaving\" level=\"8\"><p><b>Mighty Cleaving:</b> A mighty cleaving weapon allows a wielder with the Cleave feat to make one additional cleave attempt in a round.</p><p>Moderate evocation; CL 8th; Craft Magic Arms and Armor, <i>divine power</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (244,'Returning','Weapon',NULL,'Yes','Moderate transmutation','7','+1 bonus',NULL,'Craft Magic Arms and Armor, telekinesis',NULL,NULL,'\n      <div topic=\"Returning\" level=\"8\"><p><b>Returning:</b> This special ability can only be placed on a weapon that can be thrown. A returning weapon flies through the air back to the creature that threw it. It returns to the thrower just before the creature\'s next turn (and is therefore ready to use again in that turn).</p><p>Catching a returning weapon when it comes back is a free action. If the character can\'t catch it, or if the character has moved since throwing it, the weapon drops to the ground in the square from which it was thrown.</p><p>Moderate transmutation; CL 7th; Craft Magic Arms and Armor, <i>telekinesis</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (245,'Seeking','Weapon',NULL,'Yes','Strong divination','12','+1 bonus',NULL,'Craft Magic Arms and Armor, true seeing',NULL,NULL,'\n      <div topic=\"Seeking\" level=\"8\"><p><b>Seeking:</b> Only ranged weapons can have the seeking ability. The weapon veers toward its target, negating any miss chances that would otherwise apply, such as from concealment. (The wielder still has to aim the weapon at the right square. Arrows mistakenly shot into an empty space, for example, do not veer and hit invisible enemies, even if they are nearby.)</p><p>Strong divination; CL 12th; Craft Magic Arms and Armor, <i>true seeing</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (246,'Shock','Weapon',NULL,'Yes','Moderate evocation','8','+1 bonus',NULL,'Craft Magic Arms and Armor, call lightning or lightning bolt',NULL,NULL,'\n      <div topic=\"Shock\" level=\"8\"><p><b>Shock:</b> Upon command, a shock weapon is sheathed in crackling electricity. The electricity does not harm the wielder. The effect remains until another command is given. A shock weapon deals an extra 1d6 points of electricity damage on a successful hit. Bows, crossbows, and slings so crafted bestow the electricity energy upon their ammunition.</p><p>Moderate evocation; CL 8th; Craft Magic Arms and Armor, <i>call lightning</i> or <i>lightning bolt</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (247,'Shocking Burst','Weapon',NULL,'Yes','Moderate evocation','10','+2 bonus',NULL,'Craft Magic Arms and Armor, call lightning or lightning bolt',NULL,NULL,'\n      <div topic=\"Shocking Burst\" level=\"8\"><p><b>Shocking Burst:</b> A shocking burst weapon functions as a shock weapon that also explodes with electricity upon striking a successful critical hit. The electricity does not harm the wielder. In addition to the extra electricity damage from the shock ability, a shocking burst weapon deals an extra 1d10 points of electricity damage on a successful critical hit. If the weapon\'s critical multiplier is x3, add an extra 2d10 points of electricity damage instead, and if the multiplier is x4, add an extra 3d10 points. Bows, crossbows, and slings so crafted bestow the electricity energy upon their ammunition.</p><p>Even if the shock ability is not active, the weapon still deals its extra electricity damage on a successful critical hit.</p><p>Moderate evocation; CL 10th; Craft Magic Arms and Armor, <i>call lightning</i> or <i>lightning bolt</i>; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (248,'Speed','Weapon',NULL,'Yes','Moderate transmutation','7','+3 bonus',NULL,'Craft Magic Arms and Armor, haste',NULL,NULL,'\n      <div topic=\"Speed\" level=\"8\"><p><b>Speed:</b> When making a full attack action, the wielder of a speed weapon may make one extra attack with it. The attack uses the wielder\'s full base attack bonus, plus any modifiers appropriate to the situation. (This benefit is not cumulative with similar effects, such as a <i>haste</i> spell.)</p><p>Moderate transmutation; CL 7th; Craft Magic Arms and Armor, <i>haste</i>; Price +3 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (249,'Spell Storing','Weapon',NULL,'Yes','Strong evocation (plus aura of stored spell)','12','+1 bonus',NULL,'Craft Magic Arms and Armor, creator must be a caster of at least 12th level',NULL,NULL,'\n      <div topic=\"Spell Storing\" level=\"8\"><p><b>Spell Storing:</b> A spell storing weapon allows a spellcaster to store a single targeted spell of up to 3rd level in the weapon. (The spell must have a casting time of 1 standard action.) Any time the weapon strikes a creature and the creature takes damage from it, the weapon can immediately cast the spell on that creature as a free action if the wielder desires. (This special ability is an exception to the general rule that casting a spell from an item takes at least as long as casting that spell normally.) Once the spell has been cast from the weapon, a spellcaster can cast any other targeted spell of up to 3rd level into it. The weapon magically imparts to the wielder the name of the spell currently stored within it. A randomly rolled spell storing weapon has a 50% chance to have a spell stored in it already.</p><p>Strong evocation (plus aura of stored spell); CL 12th; Craft Magic Arms and Armor, creator must be a caster of at least 12th level; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (250,'Thundering','Weapon',NULL,'Yes','Faint necromancy','5','+1 bonus',NULL,'Craft Magic Arms and Armor, blindness/deafness',NULL,NULL,'\n      <div topic=\"Thundering\" level=\"8\"><p><b>Thundering:</b> A thundering weapon creates a cacophonous roar like thunder upon striking a successful critical hit. The sonic energy does not harm the wielder. A thundering weapon deals an extra 1d8 points of sonic damage on a successful critical hit. If the weapon\'s critical multiplier is x3, add an extra 2d8 points of sonic damage instead, and if the multiplier is x4, add an extra 3d8 points of sonic damage. Bows, crossbows, and slings so crafted bestow the sonic energy upon their ammunition. Subjects dealt a critical hit by a thundering weapon must make a DC 14 Fortitude save or be deafened permanently.</p><p>Faint necromancy; CL 5th; Craft Magic Arms and Armor, <i>blindness/deafness</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (251,'Throwing','Weapon',NULL,'Yes','Faint transmutation','5','+1 bonus',NULL,'Craft Magic Arms and Armor, magic stone',NULL,NULL,'\n      <div topic=\"Throwing\" level=\"8\"><p><b>Throwing:</b> This ability can only be placed on a melee weapon. A melee weapon crafted with this ability gains a range increment of 10 feet and can be thrown by a wielder proficient in its normal use.</p><p>Faint transmutation; CL 5th; Craft Magic Arms and Armor, <i>magic stone</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (252,'Unholy','Weapon',NULL,'Yes','Moderate evocation [evil]','7','+2 bonus',NULL,'Craft Magic Arms and Armor, unholy blight, creator must be evil',NULL,NULL,'\n      <div topic=\"Unholy\" level=\"8\"><p><b>Unholy:</b> An unholy weapon is imbued with unholy power. This power makes the weapon evil-aligned and thus bypasses the corresponding damage reduction. It deals an extra 2d6 points of damage against all of good alignment. It bestows one negative level on any good creature attempting to wield it. The negative level remains as long as the weapon is in hand and disappears when the weapon is no longer wielded. This negative level never results in actual level loss, but it cannot be overcome in any way (including <i>restoration</i> spells) while the weapon is wielded. Bows, crossbows, and slings so crafted bestow the unholy power upon their ammunition.</p><p>Moderate evocation [evil]; CL 7th; Craft Magic Arms and Armor, <i>unholy blight</i>,  creator must be evil; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (253,'Vicious','Weapon',NULL,'Yes','Moderate necromancy','9','+1 bonus',NULL,'Craft Magic Arms and Armor, enervation',NULL,NULL,'\n      <div topic=\"Vicious\" level=\"8\"><p><b>Vicious:</b> When a vicious weapon strikes an opponent, it creates a flash of disruptive energy that resonates between the opponent and the wielder. This energy deals an extra 2d6 points of damage to the opponent and 1d6 points of damage to the wielder. Only melee weapons can be vicious.</p><p>Moderate necromancy; CL 9th; Craft Magic Arms and Armor, <i>enervation</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (254,'Vorpal','Weapon',NULL,'Yes','Strong necromancy and transmutation','18','+5 bonus',NULL,'Craft Magic Arms and Armor, circle of death, keen edge',NULL,NULL,'\n      <div topic=\"Vorpal\" level=\"8\"><p><b>Vorpal:</b> This potent and feared ability allows the weapon to sever the heads of those it strikes. Upon a roll of natural 20 (followed by a successful roll to confirm the critical hit), the weapon severs the opponent\'s head (if it has one) from its body. Some creatures, such as many aberrations and all oozes, have no heads. Others, such as golems and undead creatures other than vampires, are not affected by the loss of their heads. Most other creatures, however, die when their heads are cut off. A vorpal weapon must be a slashing weapon. (If you roll this property randomly for an inappropriate weapon, reroll.)</p><p>Strong necromancy and transmutation; CL 18th; Craft Magic Arms and Armor,  <i>circle of death</i>, <i>keen edge</i>; Price +5 bonus.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (255,'Wounding','Weapon',NULL,'Yes','Moderate evocation','10','+2 bonus',NULL,'Craft Magic Arms and Armor, mage\'s sword',NULL,NULL,'\n      <div topic=\"Wounding\" level=\"8\"><p><b>Wounding:</b> A wounding weapon deals 1 point of Constitution damage from blood loss when it hits a creature. A critical hit does not multiply the Constitution damage. Creatures immune to critical hits (such as plants and constructs) are immune to the Constitution damage dealt by this weapon.</p><p>Moderate evocation; CL 10th; Craft Magic Arms and Armor, <i>mage\'s sword</i>; Price +2 bonus.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"6\" curcol=\"2\">\n<td colspan=\"5\"><b>Table: Specific Weapons</b><br/></td> \n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td><b>Minor</b><br/></td>\n<td><b>Medium</b><br/></td>\n<td><b>Major</b><br/></td>\n<td><b>Specific Weapon</b><br/></td>\n<td><b>Market Price</b><br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>01-15<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td><i>Sleep arrow</i><br/></td>\n<td>132 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>16-25<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td><i>Screaming bolt</i><br/></td>\n<td>267 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>26-45<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>Silver dagger, masterwork<br/></td>\n<td>322 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>46-65<br/></td>\n<td>-<br/></td>\n<td>-<br/></td>\n<td>Cold iron longsword, masterwork<br/></td>\n<td>330 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>66-75<br/></td>\n<td>01-09<br/></td>\n<td>-<br/></td>\n<td><i>Javelin of lightning</i><br/></td>\n<td>1,500 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>76-80<br/></td>\n<td>10-15<br/></td>\n<td>-<br/></td>\n<td><i>Slaying arrow</i><br/></td>\n<td>2,282 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>81-90<br/></td>\n<td>16-24<br/></td>\n<td>-<br/></td>\n<td>Adamantine dagger<br/></td>\n<td>3,002 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>91-100<br/></td>\n<td>25-33<br/></td>\n<td>-<br/></td>\n<td>Adamantine battleaxe<br/></td>\n<td>3,010 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>34-37<br/></td>\n<td>-<br/></td>\n<td><i>Slaying arrow (greater)</i><br/></td>\n<td>4,057 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>38-40<br/></td>\n<td>-<br/></td>\n<td><i>Shatterspike</i><br/></td>\n<td>4,315 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>41-46<br/></td>\n<td>-<br/></td>\n<td><i>Dagger of venom</i><br/></td>\n<td>8,302 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>47-51<br/></td>\n<td>-<br/></td>\n<td><i>Trident of warning</i><br/></td>\n<td>10,115 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>52-57<br/></td>\n<td>01-04<br/></td>\n<td><i>Assassin\'s dagger</i><br/></td>\n<td>10,302 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>58-62<br/></td>\n<td>05-07<br/></td>\n<td><i>Shifter\'s sorrow</i><br/></td>\n<td>12,780 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>63-66<br/></td>\n<td>08-09<br/></td>\n<td><i>Trident of fish command</i><br/></td>\n<td>18,650 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>67-74<br/></td>\n<td>10-13<br/></td>\n<td><i>Flame tongue</i><br/></td>\n<td>20,715 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>75-79<br/></td>\n<td>14-17<br/></td>\n<td><i>Luck blade (0 wishes)</i><br/></td>\n<td>22,060 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>80-86<br/></td>\n<td>18-24<br/></td>\n<td><i>Sword of subtlety</i><br/></td>\n<td>22,310 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>87-91<br/></td>\n<td>25-31<br/></td>\n<td><i>Sword of the planes</i><br/></td>\n<td>22,315 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>92-95<br/></td>\n<td>32-37<br/></td>\n<td><i>Nine lives stealer</i><br/></td>\n<td>23,057 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>96-98<br/></td>\n<td>38-42<br/></td>\n<td><i>Sword of life stealing</i><br/></td>\n<td>25,715 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>99-100<br/></td>\n<td>43-46<br/></td>\n<td><i>oathbow</i><br/></td>\n<td>25,600 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>47-51<br/></td>\n<td><i>Mace of terror</i><br/></td>\n<td>38,552 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>52-57<br/></td>\n<td><i>Life-drinker</i><br/></td>\n<td>40,320 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>58-62<br/></td>\n<td><i>Sylvan scimitar</i><br/></td>\n<td>47,315 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>63-67<br/></td>\n<td><i>Rapier of puncturing</i><br/></td>\n<td>50,320 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>68-73<br/></td>\n<td><i>Sun blade</i><br/></td>\n<td>50,335 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>74-79<br/></td>\n<td><i>Frost brand</i><br/></td>\n<td>54,475 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>80-84<br/></td>\n<td><i>Dwarven thrower</i><br/></td>\n<td>60,312 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>85-91<br/></td>\n<td><i>Luck blade (1 wish)</i><br/></td>\n<td>62,360 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>92-95<br/></td>\n<td><i>Mace of smiting</i><br/></td>\n<td>75,312 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>96-97<br/></td>\n<td><i>Luck blade (2 wishes)</i><br/></td>\n<td>102,660 gp<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>98-99<br/></td>\n<td><i>Holy avenger</i><br/></td>\n<td>120,630 gp<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>-<br/></td>\n<td>-<br/></td>\n<td>100<br/></td>\n<td><i>Luck blade (3 wishes)</i><br/></td>\n<td>142,960 gp<br/></td>\n\n</tr>\n</table><p/>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (256,'Adamantine Battleaxe','Weapon',NULL,'No','No aura (nonmagical)',NULL,'3,010 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Adamantine Battleaxe\" level=\"8\"><p><b>Adamantine Battleaxe:</b> This nonmagical axe is made out of adamantine. As a masterwork weapon, it has a +1 enhancement bonus on attack rolls.</p><p>No aura (nonmagical); Price 3,010 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (257,'Adamantine Dagger','Weapon',NULL,'No','No aura (nonmagical)',NULL,'3,002 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Adamantine Dagger\" level=\"8\"><p><b>Adamantine Dagger:</b> This nonmagical dagger is made out of adamantine. As a masterwork weapon, it has a +1 enhancement bonus on attack rolls.</p><p>No aura (nonmagical); Price 3,002 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (258,'Assassin\'s Dagger','Weapon',NULL,'No','Moderate necromancy','9','18,302 gp',NULL,'Craft Magic Arms and Armor, slay living','9,302 gp + 720 XP',NULL,'\n      <div topic=\"Assassin\'s Dagger\" level=\"8\"><p><b>Assassin\'s Dagger:</b> This wicked-looking, curved <i>+2 dagger</i> provides a +1 bonus to the DC of a Fortitude save forced by the death attack of an assassin.</p><p>Moderate necromancy; CL 9th; Craft Magic Arms and Armor, <i>slay living</i>; Price 18,302 gp; Cost 9,302 gp + 720 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (259,'Dagger of Venom','Weapon',NULL,'No','Faint necromancy','5','8,302 gp',NULL,'Craft Magic Arms and Armor, poison','4,302 gp + 320 XP',NULL,'\n      <div topic=\"Dagger of Venom\" level=\"8\"><p><b>Dagger of Venom:</b> This black <i>+1 dagger</i> has a serrated edge. It allows the wielder to use a <i>poison</i> effect (as the spell, save DC 14) upon a creature struck by the blade once per day. The wielder can decide to use the power after he has struck. Doing so is a free action, but the <i>poison</i> effect must be invoked in the same round that the dagger strikes.</p><p>Faint necromancy; CL 5th; Craft Magic Arms and Armor, <i>poison</i>; Price 8,302 gp; Cost 4,302 gp + 320 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (260,'Dwarven Thrower','Weapon',NULL,'No','Moderate evocation','10','60,312 gp',NULL,'Craft Magic Arms and Armor, creator must be a dwarf of at least 10th level','30,312 gp + 2,400 XP',NULL,'\n      <div topic=\"Dwarven Thrower\" level=\"8\"><p><b>Dwarven Thrower:</b> This weapon commonly functions as a <i>+2 warhammer</i>. In the hands of a dwarf, the warhammer gains an additional +1 enhancement bonus (for a total enhancement bonus of +3) and gains the returning special ability. It can be hurled with a 30-foot range increment. When hurled, it deals an extra 2d8 points of damage against giants or an extra 1d8 points of damage against any other target.</p><p>Moderate evocation; CL 10th; Craft Magic Arms and Armor, creator must be a dwarf of at least 10th level; Price 60,312 gp; Cost 30,312 gp + 2,400 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (261,'Flame Tongue','Weapon',NULL,'No','Moderate evocation','12','20,715 gp',NULL,'Craft Magic Arms and Armor, scorching ray, and flame blade, flame strike, or fireball','10,515 gp + 816 XP',NULL,'\n      <div topic=\"Flame Tongue\" level=\"8\"><p><b>Flame Tongue:</b> This is a <i>+1 flaming burst longsword</i>. Once per day, the sword can blast forth a fiery ray at any target within 30 feet as a ranged touch attack. The ray deals 4d6 points of fire damage on a successful hit.</p><p>Moderate evocation; CL 12th; Craft Magic Arms and Armor, <i>scorching ray</i>,  and <i>flame blade</i>,  <i>flame strike</i>,  or <i>fireball</i>; Price 20,715 gp; Cost 10,515 gp + 816 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (262,'Frost Brand','Weapon',NULL,'No','Strong evocation','14','54,475 gp',NULL,'Craft Magic Arms and Armor, ice storm, dispel magic, protection from energy','27,375 gp and 5 sp + 2179 XP',NULL,'\n      <div topic=\"Frost Brand\" level=\"8\"><p><b>Frost Brand:</b> This <i>+3 frost greatsword</i> sheds light as a torch when the temperature drops below 0&#xB0;F. At such times it cannot be concealed when drawn, nor can its light be shut off. Its wielder is protected from fire; the sword absorbs the first 10 points of fire damage each round that the wielder would otherwise take.</p><p>A <i>frost brand</i> extinguishes all nonmagical fires in its area. As a standard action, it can also dispel lasting fire spells,  but not instantaneous effects,  though you must succeed on a dispel check (1d20 +14) against each spell to dispel it. The DC to dispel such spells is 11 + the caster level of the fire spell.</p><p>Strong evocation; CL 14th; Craft Magic Arms and Armor, <i>ice storm</i>,  <i>dispel magic</i>,  <i>protection from energy</i>; Price 54,475 gp; Cost 27,375 gp and 5 sp + 2179 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (263,'Holy Avenger','Weapon',NULL,'No','Strong abjuration','18','120,630 gp',NULL,'Craft Magic Arms and Armor, holy aura, creator must be good','60,630 gp + 4,800 XP',NULL,'\n      <div topic=\"Holy Avenger\" level=\"8\"><p><b>Holy Avenger:</b> This <i>+2 cold iron longsword</i> becomes a <i>+5 holy cold iron longsword</i> in the hands of a paladin.</p><p>It provides spell resistance of 5 + the paladin\'s level to the wielder and anyone adjacent to her. It also enables the wielder to use <i>greater dispel magic</i> (once per round as a standard action) at the class level of the paladin. (Only the area dispel is possible, not the targeted dispel or counterspell versions of <i>greater dispel magic</i>.)</p><p>Strong abjuration; CL 18th; Craft Magic Arms and Armor, <i>holy aura</i>,  creator must be good; Price 120,630 gp; Cost 60,630 gp + 4,800 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (264,'Javelin of Lightning','Weapon',NULL,'No','Faint evocation','5','1,500 gp',NULL,'Craft Magic Arms and Armor, lightning bolt','750 gp + 30 XP',NULL,'\n      <div topic=\"Javelin of Lightning\" level=\"8\"><p><b>Javelin of Lightning:</b> This javelin becomes a 5d6 <i>lightning bolt</i> when thrown (Reflex DC 14 half ). It is consumed in the attack.</p><p>Faint evocation; CL 5th; Craft Magic Arms and Armor, <i>lightning bolt</i>; Price 1,500 gp; Cost 750 gp + 30 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (265,'Life-Drinker','Weapon',NULL,'No','Strong necromancy','13','40,320 gp',NULL,'Craft Magic Arms and Armor, enervation','20,320 gp + 1,600 XP',NULL,'\n      <div topic=\"Life-Drinker\" level=\"8\"><p><b>Life-Drinker:</b> This <i>+1 greataxe</i> is favored by undead and constructs, who do not suffer its drawback. A <i>life-drinker</i> bestows two negative levels on its target whenever it deals damage, just as if its target had been struck by an undead creature. One day after being struck, subjects must make a DC 16 Fortitude save for each negative level or lose a character level.</p><p>Each time a <i>life-drinker</i> deals damage to a foe, it also bestows one negative level on the wielder. Any negative level gained by the wielder in this fashion lasts for 1 hour.</p><p>Strong necromancy; CL 13th; Craft Magic Arms and Armor, <i>enervation</i>; Price 40,320 gp; Cost 20,320 gp + 1,600 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (266,'Luck Blade (0 wishes)','Weapon',NULL,'No','Strong evocation','17','22,060 gp',NULL,'Craft Magic Arms and Armor, wish or miracle','11,030 gp + 882 XP',NULL,'\n      <div topic=\"Luck Blade\" level=\"8\"><p><b>Luck Blade:</b> This <i>+2 short sword</i> gives its possessor a +1 luck bonus on all saving throws. Its possessor also gains the power of good fortune, usable once per day. This extraordinary ability allows its possessor to reroll one roll that she just made. She must take the result of the reroll, even if it\'s worse than the original roll. In addition, a <i>luck blade</i> may contain up to three <i>wishes</i> (when randomly rolled, a <i>luck blade</i> holds 1d4-1 <i>wishes</i>,  minimum 0). When the last <i>wish</i> is used, the sword remains a <i>+2 short sword</i>,  still grants the +1 luck bonus, and still grants its reroll power.</p><p>Strong evocation; CL 17th; Craft Magic Arms and Armor, <i>wish</i> or <i>miracle</i>; Price 22,060 gp (0 <i>wishes</i>), 62,360 gp (1 <i>wish</i>), 102,660 gp (2 <i>wishes</i>), 142,960 gp (3 <i>wishes</i>); Cost 11,030 gp + 882 XP (0 <i>wishes</i>), 31,180 gp + 2,494 XP (1 <i>wish</i>), 51,330 gp + 4,106 XP (2 <i>wishes</i>), 71,480 gp + 5,718 XP (3 <i>wishes</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (267,'Luck Blade (1 wish)','Weapon',NULL,'No','Strong evocation','17','62,360 gp',NULL,'Craft Magic Arms and Armor, wish or miracle','31,180 gp + 2,494 XP',NULL,'\n      <div topic=\"Luck Blade\" level=\"8\"><p><b>Luck Blade:</b> This <i>+2 short sword</i> gives its possessor a +1 luck bonus on all saving throws. Its possessor also gains the power of good fortune, usable once per day. This extraordinary ability allows its possessor to reroll one roll that she just made. She must take the result of the reroll, even if it\'s worse than the original roll. In addition, a <i>luck blade</i> may contain up to three <i>wishes</i> (when randomly rolled, a <i>luck blade</i> holds 1d4-1 <i>wishes</i>,  minimum 0). When the last <i>wish</i> is used, the sword remains a <i>+2 short sword</i>,  still grants the +1 luck bonus, and still grants its reroll power.</p><p>Strong evocation; CL 17th; Craft Magic Arms and Armor, <i>wish</i> or <i>miracle</i>; Price 22,060 gp (0 <i>wishes</i>), 62,360 gp (1 <i>wish</i>), 102,660 gp (2 <i>wishes</i>), 142,960 gp (3 <i>wishes</i>); Cost 11,030 gp + 882 XP (0 <i>wishes</i>), 31,180 gp + 2,494 XP (1 <i>wish</i>), 51,330 gp + 4,106 XP (2 <i>wishes</i>), 71,480 gp + 5,718 XP (3 <i>wishes</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (268,'Luck Blade (2 wishes)','Weapon',NULL,'No','Strong evocation','17','102,660 gp',NULL,'Craft Magic Arms and Armor, wish or miracle','51,330 gp + 4,106 XP',NULL,'\n      <div topic=\"Luck Blade\" level=\"8\"><p><b>Luck Blade:</b> This <i>+2 short sword</i> gives its possessor a +1 luck bonus on all saving throws. Its possessor also gains the power of good fortune, usable once per day. This extraordinary ability allows its possessor to reroll one roll that she just made. She must take the result of the reroll, even if it\'s worse than the original roll. In addition, a <i>luck blade</i> may contain up to three <i>wishes</i> (when randomly rolled, a <i>luck blade</i> holds 1d4-1 <i>wishes</i>,  minimum 0). When the last <i>wish</i> is used, the sword remains a <i>+2 short sword</i>,  still grants the +1 luck bonus, and still grants its reroll power.</p><p>Strong evocation; CL 17th; Craft Magic Arms and Armor, <i>wish</i> or <i>miracle</i>; Price 22,060 gp (0 <i>wishes</i>), 62,360 gp (1 <i>wish</i>), 102,660 gp (2 <i>wishes</i>), 142,960 gp (3 <i>wishes</i>); Cost 11,030 gp + 882 XP (0 <i>wishes</i>), 31,180 gp + 2,494 XP (1 <i>wish</i>), 51,330 gp + 4,106 XP (2 <i>wishes</i>), 71,480 gp + 5,718 XP (3 <i>wishes</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (269,'Luck Blade (3 wishes)','Weapon',NULL,'No','Strong evocation','17','142,960 gp',NULL,'Craft Magic Arms and Armor, wish or miracle','71,480 gp + 5,718 XP',NULL,'\n      <div topic=\"Luck Blade\" level=\"8\"><p><b>Luck Blade:</b> This <i>+2 short sword</i> gives its possessor a +1 luck bonus on all saving throws. Its possessor also gains the power of good fortune, usable once per day. This extraordinary ability allows its possessor to reroll one roll that she just made. She must take the result of the reroll, even if it\'s worse than the original roll. In addition, a <i>luck blade</i> may contain up to three <i>wishes</i> (when randomly rolled, a <i>luck blade</i> holds 1d4-1 <i>wishes</i>,  minimum 0). When the last <i>wish</i> is used, the sword remains a <i>+2 short sword</i>,  still grants the +1 luck bonus, and still grants its reroll power.</p><p>Strong evocation; CL 17th; Craft Magic Arms and Armor, <i>wish</i> or <i>miracle</i>; Price 22,060 gp (0 <i>wishes</i>), 62,360 gp (1 <i>wish</i>), 102,660 gp (2 <i>wishes</i>), 142,960 gp (3 <i>wishes</i>); Cost 11,030 gp + 882 XP (0 <i>wishes</i>), 31,180 gp + 2,494 XP (1 <i>wish</i>), 51,330 gp + 4,106 XP (2 <i>wishes</i>), 71,480 gp + 5,718 XP (3 <i>wishes</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (270,'Mace of Smiting','Weapon',NULL,'No','Moderate transmutation','11','75,312 gp',NULL,'Craft Magic Arms and Armor, disintegrate','39,312 gp + 2,880 XP',NULL,'\n      <div topic=\"Mace of Smiting\" level=\"8\"><p><b>Mace of Smiting:</b> This <i>+3 adamantine heavy mace</i> has a +5 enhancement bonus against constructs, and any critical hit dealt to a construct completely destroys it (no saving throw). A critical hit dealt to an outsider deals x4 damage rather than x2.</p><p>Moderate transmutation; CL 11th; Craft Magic Arms and Armor, <i>disintegrate</i>; Price 75,312 gp; Cost 39,312 gp + 2,880 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (271,'Mace of Terror','Weapon',NULL,'No','Strong necromancy','13','38,552 gp',NULL,'Craft Magic Arms and Armor, fear','19,276 gp + 1,542 XP',NULL,'\n      <div topic=\"Mace of Terror\" level=\"8\"><p><b>Mace of Terror:</b> On command, this <i>+2 heavy mace</i> causes the wielder\'s clothes and appearance to transform into an illusion of darkest horror such that living creatures in a 30-foot cone become panicked as if by a <i>fear</i> spell (Will DC 16 partial). They take a -2 morale penalty on saving throws, and they flee from the wielder. The wielder may use this ability up to three times per day.</p><p>Strong necromancy; CL 13th; Craft Magic Arms and Armor, <i>fear</i>; Price 38,552 gp; Cost 19,276 gp + 1,542 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (272,'Masterwork Cold Iron Longsword','Weapon',NULL,'No','No aura (nonmagical)',NULL,'330 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Masterwork Cold Iron Longsword\" level=\"8\"><p><b>Masterwork Cold Iron Longsword:</b> This nonmagical longsword is crafted out of cold iron. As a masterwork weapon, it has a +1 enhancement bonus on attack rolls.</p><p>No aura (nonmagical); Price 330 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (273,'Nine Lives Stealer','Weapon',NULL,'No','Strong necromancy [evil]','13','23,057 gp',NULL,'Craft Magic Arms and Armor, finger of death','11,528 gp 5 sp + 922 XP',NULL,'\n      <div topic=\"Nine Lives Stealer\" level=\"8\"><p><b>Nine Lives Stealer:</b> This longsword always performs as a <i>+2 longsword</i>,  but it also has the power to draw the life force from an opponent. It can do this nine times before the ability is lost. At that point, the sword becomes a simple <i>+2 longsword</i> (with a hint of evil about it). A critical hit must be dealt for the sword\'s death-dealing ability to function, and this weapon has no effect on creatures not subject to critical hits. The victim is entitled to a DC 20 Fortitude save to avoid death. If the save is successful, the sword\'s death-dealing ability does not function, no use of the ability is expended, and normal critical damage is determined. This sword is evil, and any good character attempting to wield it gains two negative levels. These negative levels remain as long as the sword is in hand and disappear when the sword is no longer wielded. These negative levels never result in actual level loss, but they cannot be overcome in any way (including <i>restoration</i> spells) while the sword is wielded.</p><p>Strong necromancy [evil]; CL 13th; Craft Magic Arms and Armor, <i>finger of death</i>; Price 23,057 gp; Cost 11,528 gp 5 sp + 922 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (274,'Oathbow','Weapon',NULL,'No','Strong evocation','15','25,600 gp',NULL,'Craft Magic Arms and Armor, creator must be an elf','13,100 gp + 1,000 XP',NULL,'\n      <div topic=\"Oathbow\" level=\"8\"><p><b>Oathbow:</b> Of elven make, this white <i>+2 composite longbow</i> (+2 Str bonus) whispers \'Swift defeat to my enemies\' in Elven when nocked and pulled. Once per day, if the firer swears aloud to slay her target (a free action), the bow\'s whisper becomes the low shout \'Swift death to those who have wronged me.\' Against such a sworn enemy, the bow has a +5 enhancement bonus, and arrows launched from it deal an additional 2d6 points of damage (and x4 on a critical hit instead of the normal x3). However, the bow is treated as only a masterwork weapon against all foes other than the sworn enemy, and the wielder takes a -1 penalty on attack rolls with any weapon other than the <i>oathbow</i>. These bonuses and penalties last for seven days or until the sworn enemy is slain or destroyed by the wielder of the <i>oathbow</i>,  whichever comes first.</p><p>The <i>oathbow</i> may only have one sworn enemy at a time. Once the wielder swears to slay a target, he cannot make a new oath until he has slain that target or seven days have passed. Even if the wielder slays the sworn enemy on the same day that he makes the oath, he cannot activate the <i>oathbow</i>\'s special power again until 24 hours have passed from the time he made the oath.</p><p>Strong evocation; CL 15th; Craft Magic Arms and Armor, creator must be an elf; Price 25,600 gp; Cost 13,100 gp + 1,000 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (275,'Rapier of Puncturing','Weapon',NULL,'No','Strong necromancy','13','50,320 gp',NULL,'Craft Magic Arms and Armor, harm','25,320 gp + 2,000 XP',NULL,'\n      <div topic=\"Rapier of Puncturing\" level=\"8\"><p><b>Rapier of Puncturing:</b> Three times per day, this <i>+2 wounding rapier</i> allows the wielder to make a touch attack with the weapon that deals 1d6 points of Constitution damage by draining blood. Creatures immune to critical hits are immune to the Constitution damage dealt by this weapon.</p><p>Strong necromancy; CL 13th; Craft Magic Arms and Armor, <i>harm</i>; Price 50,320 gp; Cost 25,320 gp + 2,000 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (276,'Screaming Bolt','Weapon',NULL,'No','Faint enchantment','5','267gp',NULL,'Craft Magic Arms and Armor, doom','128 gp and 5 sp + 10 XP',NULL,'\n      <div topic=\"Screaming Bolt\" level=\"8\"><p><b>Screaming Bolt:</b> One of these <i>+2 bolts</i> screams when fired, forcing all enemies of the wielder within 20 feet of the path of the bolt to succeed on a DC 14 Will save or become shaken. This is a mind-affecting fear effect.</p><p>Faint enchantment; CL 5th; Craft Magic Arms and Armor, <i>doom</i>; Price 267gp; Cost 128 gp and 5 sp + 10 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (277,'Shatterspike','Weapon',NULL,'No','Strong evocation','13','4,315 gp',NULL,'Str 13, Craft Arms and Armor, Power Attack, Improved Sunder, shatter','2,315 gp + 160 XP','4 lb','\n      <div topic=\"Shatterspike\" level=\"8\"><p><b>Shatterspike:</b> Wielders without the Improved Sunder feat use <i>Shatterspike</i> as a <i>+1 longsword</i> only; wielders with the Improved Sunder feat add a +4 bonus (including the sword\'s +1 enhancement bonus) to the opposed roll when attempting to strike a foe\'s weapon. If successful, <i>Shatterspike</i> deals 1d8+4 points of damage plus the wielder\'s Strength modifier to the target weapon (the target weapon\'s hardness must still be overcome with each hit). <i>Shatterspike</i> can damage weapons with an enhancement bonus of +4 or lower.</p><p>Strong evocation; CL 13th; Str 13, Craft Arms and Armor, Power Attack, Improved Sunder, <i>shatter</i>; Price 4,315 gp; Cost 2,315 gp + 160 XP; Weight 4 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (278,'Shifter\'s Sorrow','Weapon',NULL,'No','Strong transmutation','15','12,780 gp',NULL,'Craft Arms and Armor, baleful polymorph','6,780 gp + 480 XP','10 lb','\n      <div topic=\"Shifter\'s Sorrow\" level=\"8\"><p><b>Shifter\'s Sorrow:</b> This <i>+1/+1 two-bladed sword</i> has blades of alchemical silver. The weapon deals an extra 2d6 points of damage against any creature with the shapechanger subtype. When a shapechanger or a creature in an alternate form (such as a druid using wild shape) is struck by the weapon, it must make a DC 15 Will save or return to its natural form.</p><p>Strong transmutation; CL 15th; Craft Arms and Armor, <i>baleful polymorph</i>; Price 12,780 gp; Cost 6,780 gp + 480 XP; Weight 10 lb.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (279,'Silver Dagger, Masterwork','Weapon',NULL,'No','No aura (nonmagical)',NULL,'322 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Silver Dagger, Masterwork\" level=\"8\"><p><b>Silver Dagger, Masterwork:</b> This masterwork alchemical silver dagger is nonmagical. As a masterwork weapon, it has a +1 enhancement bonus on attack rolls.</p><p>No aura (nonmagical); Price 322 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (280,'Slaying Arrow, Greater','Weapon',NULL,'No','Strong necromancy','13','or 4,057 gp',NULL,'Craft Magic Arms and Armor, finger of death (Slaying arrow) or heightened finger of death (greater slaying arrow)','or 2,032 gp + 162 XP',NULL,'\n      <div topic=\"Slaying Arrow\" level=\"8\"><p><b>Slaying Arrow:</b> This <i>+1 arrow</i> is keyed to a particular type or subtype of creature. If it strikes such a creature, the target must make a DC 20 Fortitude save or die (or, in the case of unliving targets, be destroyed) instantly. Note that even creatures normally exempt from Fortitude saves (undead and constructs) are subject to this attack. When keyed to a living creature, this is a death effect (and thus <i>death ward</i> protects a target). To determine the type or subtype of creature the arrow is keyed to, roll on the table below.</p><p>A <i>greater slaying arrow</i> functions just like a normal <i>Slaying arrow</i>,  but the DC to avoid the death effect is 23.</p><p>Strong necromancy; CL 13th; Craft Magic Arms and Armor, <i>finger of death</i> (<i>Slaying arrow</i>) or heightened <i>finger of death</i> (<i>greater slaying arrow</i>); Price 2,282 gp (<i>Slaying arrow</i>) or 4,057 gp (<i>greater slaying arrow</i>); Cost 1,144 gp 5 sp + 91 XP (<i>Slaying arrow</i>) or 2,032 gp + 162 XP (<i>greater slaying arrow</i>).</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>d%</b><br/></td> <td><b>Designated Type or Subtype</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>01-05<br/></td>\n<td>Aberrations<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>06-09<br/></td>\n<td>Animals<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>10-16<br/></td>\n<td>Constructs<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>17-22<br/></td>\n<td>Dragons<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>23-27<br/></td>\n<td>Elementals<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>28-32<br/></td>\n<td>Fey<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>33-39<br/></td>\n<td>Giants<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>40<br/></td>\n<td>Humanoids, aquatic<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>41-42<br/></td>\n<td>Humanoids, dwarf<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>43-44<br/></td>\n<td>Humanoids, elf<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>45<br/></td>\n<td>Humanoids, gnoll<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>46<br/></td>\n<td>Humanoids, gnome<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>47-49<br/></td>\n<td>Humanoids, goblinoid<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>50<br/></td>\n<td>Humanoids, halfling<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>51-54<br/></td>\n<td>Humanoids, human<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>55-57<br/></td>\n<td>Humanoids, reptilian<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>58-60<br/></td>\n<td>Humanoids, orc<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>61-65<br/></td>\n<td>Magical beasts<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>66-70<br/></td>\n<td>Monstrous humanoids<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>71-72<br/></td>\n<td>Oozes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>73<br/></td>\n<td>Outsiders, air<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>74-76<br/></td>\n<td>Outsiders, chaotic<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>77<br/></td>\n<td>Outsiders, earth<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>78-80<br/></td>\n<td>Outsiders, evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>81<br/></td>\n<td>Outsiders, fire<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>82-84<br/></td>\n<td>Outsiders, good<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>85-87<br/></td>\n<td>Outsiders, lawful<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>88<br/></td>\n<td>Outsiders, water<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>89-90<br/></td>\n<td>Plants<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>91-98<br/></td>\n<td>Undead<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>99-100<br/></td>\n<td>Vermin<br/></td>\n\n</tr>\n</table>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (281,'Sleep Arrow','Weapon',NULL,'No','Faint enchantment','5','132 gp',NULL,'Craft Magic Arms and Armor, sleep','69 gp 5 sp + 5 XP',NULL,'\n      <div topic=\"Sleep Arrow\" level=\"8\"><p><b>Sleep Arrow:</b> This <i>+1 arrow</i> is painted white and has white fletching. If it strikes a foe so that it would normally deal damage, it instead bursts into magical energy that deals nonlethal damage (in the same amount as would be lethal damage) and forces the target to make a DC 11 Will save or fall asleep.</p><p>Faint enchantment; CL 5th; Craft Magic Arms and Armor, <i>sleep</i>; Price 132 gp; Cost 69 gp 5 sp + 5 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (282,'Sun Blade','Weapon',NULL,'No','Moderate evocation','10','50,335 gp',NULL,'Craft Magic Arms and Armor, daylight, creator must be good','25,335 gp + 2,000 XP',NULL,'\n      <div topic=\"Sun Blade\" level=\"8\"><p><b>Sun Blade:</b> This sword is the size of a bastard sword. However, a <i>sun blade</i> is wielded as if it were a short sword with respect to weight and ease of use. (In other words, the weapon appears to all viewers to be a bastard sword, and deals bastard sword damage, but the wielder feels and reacts as if the weapon were a short sword.) Any individual able to use either a bastard sword or a short sword with proficiency is proficient in the use of a <i>sun blade</i>. Likewise, Weapon Focus and Weapon Specialization in short sword and bastard sword apply equally, but the benefits of those feats do not stack.</p><p>In normal combat, the glowing golden blade of the weapon is equal to a <i>+2 bastard sword</i>. Against evil creatures, its enhancement bonus is +4. Against Negative Energy Plane creatures or undead creatures, the sword deals double damage (and x3 on a critical hit instead of the usual x2).</p><p>The blade also has a special <i>sunlight</i> power. Once per day, the wielder can swing the blade vigorously above her head while speaking a command word. The <i>sunblade</i> then sheds a bright yellow radiance that is like full daylight. The radiance begins shining in a 10-foot radius around the sword wielder and extends outward at 5 feet per round for 10 rounds thereafter, to create a globe of light with a 60-foot radius. When the wielder stops swinging, the radiance fades to a dim glow that persists for another minute before disappearing entirely. All <i>sun blades</i> are of good alignment, and any evil creature attempting to wield one gains one negative level. The negative level remains as long as the sword is in hand and disappears when the sword is no longer wielded. This negative level never results in actual level loss, but it cannot be overcome in any way (including <i>restoration</i> spells) while the sword is wielded.</p><p>Moderate evocation; CL 10th; Craft Magic Arms and Armor, <i>daylight</i>,  creator must be good; Price 50,335 gp; Cost 25,335 gp + 2,000 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (283,'Sword of Life Stealing','Weapon',NULL,'No','Strong necromancy','17','25,715 gp',NULL,'Craft Magic Arms and Armor, enervation','12,857 gp and 5 sp + 1,029 XP',NULL,'\n      <div topic=\"Sword of Life Stealing\" level=\"8\"><p><b>Sword of Life Stealing:</b> This black iron <i>+2 longsword</i> bestows a negative level when it deals a critical hit. The sword wielder gains 1d6 temporary hit points each time a negative level is bestowed on another. These temporary hit points last for 24 hours. One day after being struck, subjects must make a DC 16 Fortitude save for each negative level or lose a character level.</p><p>Strong necromancy; CL 17th; Craft Magic Arms and Armor, <i>enervation</i>; Price 25,715 gp; Cost 12,857 gp and 5 sp + 1,029 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (284,'Sword of the Planes','Weapon',NULL,'No','Strong evocation','15','22,315 gp',NULL,'Craft Magic Arms and Armor, plane shift','11,157 gp and 5 sp + 893 XP',NULL,'\n      <div topic=\"Sword of the Planes\" level=\"8\"><p><b>Sword of the Planes:</b> This longsword has an enhancement bonus of +1 on the Material Plane, but on any Elemental Plane its enhancement bonus increases to +2. (The +2 enhancement bonus also applies on the Material Plane when the weapon is used against elementals.) It operates as a <i>+3 longsword</i> on the Astral Plane or the Ethereal Plane or when used against opponents native to either of those planes. On any other plane, or against any outsider, it functions as a <i>+4 longsword</i>.</p><p>Strong evocation; CL 15th; Craft Magic Arms and Armor, <i>plane shift</i>; Price 22,315 gp; Cost 11,157 gp and 5 sp + 893 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (285,'Sword of Subtlety','Weapon',NULL,'No','Moderate illusion','7','22,310 gp',NULL,'Craft Magic Arms and Armor, blur','11,155 gp + 892 XP',NULL,'\n      <div topic=\"Sword of Subtlety\" level=\"8\"><p><b>Sword of Subtlety:</b> A <i>+1 short sword</i> with a thin, dull gray blade, this weapon provides a +4 bonus on its wielder\'s attack and damage rolls when he is making a sneak attack with it.</p><p>Moderate illusion; CL 7th; Craft Magic Arms and Armor, <i>blur</i>; Price 22,310 gp; Cost 11,155 gp + 892 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (286,'Sylvan Scimitar','Weapon',NULL,'No','Moderate evocation','11','47,315gp',NULL,'Craft Magic Arms and Armor, divine power or creator must be a 7th-level druid','23,657 gp and 5 sp + 1,893 XP',NULL,'\n      <div topic=\"Sylvan Scimitar\" level=\"8\"><p><b>Sylvan Scimitar:</b> This <i>+3 scimitar</i>,  when used outdoors in a temperate climate, grants its wielder the use of the Cleave feat and deals an extra 1d6 points of damage.</p><p>Moderate evocation; CL 11th; Craft Magic Arms and Armor, <i>divine power</i> or creator must be a 7th-level druid; Price 47,315gp; Cost 23,657 gp and 5 sp + 1,893 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (287,'Trident of Fish Command','Weapon',NULL,'No','Moderate enchantment','7','18,650 gp',NULL,'Craft Magic Arms and Armor, speak with animals','9,325 gp + 746 XP',NULL,'\n      <div topic=\"Trident of Fish Command\" level=\"8\"><p><b>Trident of Fish Command:</b> The magical properties of this <i>+1 trident</i> with a 6-foot-long haft enable its wielder to <i>charm</i> up to 14 HD of aquatic animals (Will DC 16 negates, animals get a +5 bonus if currently under attack by the wielder or his allies), no two of which can be more than 30 feet apart. The wielder can use this effect up to three times per day. The wielder can communicate with the animals as if using a <i>speak with animals</i> spell. Animals making their saving throw are free of control, but they will not approach within 10 feet of the trident. The trident can be used up to three times per day.</p><p>Moderate enchantment; CL 7th; Craft Magic Arms and Armor, <i>speak with animals</i>; Price 18,650 gp; Cost 9,325 gp + 746 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsII');
INSERT INTO item VALUES (288,'Trident of Warning','Weapon',NULL,'No','Moderate divination','7','10,115 gp',NULL,'Craft Magic Arms and Armor, locate creature','5,057 gp and 5 sp + 405 XP',NULL,'\n      <div topic=\"Trident of Warning\" level=\"8\"><p><b>Trident of Warning:</b> A weapon of this type enables its wielder to determine the location, depth, kind, and number of aquatic predators within 680 feet. A <i>trident of warning</i> must be grasped and pointed in order for the character using it to gain such information, and it requires 1 round to scan a hemisphere with a radius of 680 feet. The weapon is otherwise a <i>+2 trident</i>.</p><p>Moderate divination; CL 7th; Craft Magic Arms and Armor, <i>locate creature</i>; Price 10,115 gp; Cost 5,057 gp and 5 sp + 405 XP.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsII');
